    def test_nav_keeps_zoom_when_not_presenting(self):
        with tempfile.TemporaryDirectory() as d:
            pdf = os.path.join(d, "deck.pdf")
            make_pdf(pdf, n_pages=4)

            def body(win):
                win._do_open_file(pdf)
